/**
 * <div id="class.intllistformatter" class="reference"> <h1 class="title">The IntlListFormatter class</h1>  <div class="partintro"><p class="verinfo">(No version information available, might only be in Git)</p>    <div class="section" id="intllistformatter.intro">   <h2 class="title">简介</h2>   <p class="simpara">    Formats, orders, and punctuates a list of items according to locale-specific rules.    Requires ICU 67 or later.   </p>  </div>    <div class="section" id="intllistformatter.synopsis">   <h2 class="title">类摘要</h2>      <div class="classsynopsis"><div class="classsynopsisinfo">         <span class="modifier">class</span> <strong class="classname"><strong class="classname">IntlListFormatter</strong></strong>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>    <div class="fieldsynopsis">     <span class="modifier">public</span>     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.intllistformatter.php#intllistformatter.constants.type-and"><var class="varname">TYPE_AND</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.intllistformatter.php#intllistformatter.constants.type-or"><var class="varname">TYPE_OR</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.intllistformatter.php#intllistformatter.constants.type-units"><var class="varname">TYPE_UNITS</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.intllistformatter.php#intllistformatter.constants.width-wide"><var class="varname">WIDTH_WIDE</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.intllistformatter.php#intllistformatter.constants.width-short"><var class="varname">WIDTH_SHORT</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="modifier">const</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>      <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.intllistformatter.php#intllistformatter.constants.width-narrow"><var class="varname">WIDTH_NARROW</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/intllistformatter.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$locale</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$type</span><span class="initializer"> = <strong><span>{@link IntlListFormatter::TYPE_AND}</span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$width</span><span class="initializer"> = <strong><span>{@link IntlListFormatter::WIDTH_WIDE}</span></strong></span></span>)</div>    <div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/intllistformatter.format.php" class="methodname" style="color:#CC7832">format</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$list</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.singleton.php" class="type false" style="color:#EAB766">false</a></span></span></div>   }</div>     </div>  <div class="section" id="intllistformatter.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="intllistformatter.constants.type-and"><strong><span>{@link IntlListFormatter::TYPE_AND}</span></strong></dt>     <dd>      <span class="simpara">       Formats a list using conjunction (e.g. "A, B, and C").      </span>     </dd>             <dt id="intllistformatter.constants.type-or"><strong><span>{@link IntlListFormatter::TYPE_OR}</span></strong></dt>     <dd>      <span class="simpara">       Formats a list using disjunction (e.g. "A, B, or C").      </span>     </dd>             <dt id="intllistformatter.constants.type-units"><strong><span>{@link IntlListFormatter::TYPE_UNITS}</span></strong></dt>     <dd>      <span class="simpara">       Formats a list of units (e.g. "3 ft, 7 in").      </span>     </dd>             <dt id="intllistformatter.constants.width-wide"><strong><span>{@link IntlListFormatter::WIDTH_WIDE}</span></strong></dt>     <dd>      <span class="simpara">       Uses the widest (most verbose) list format, typically with conjunctions spelled out in full.      </span>     </dd>             <dt id="intllistformatter.constants.width-short"><strong><span>{@link IntlListFormatter::WIDTH_SHORT}</span></strong></dt>     <dd>      <span class="simpara">       Uses a short list format, typically using abbreviations.      </span>     </dd>             <dt id="intllistformatter.constants.width-narrow"><strong><span>{@link IntlListFormatter::WIDTH_NARROW}</span></strong></dt>     <dd>      <span class="simpara">       Uses the narrowest list format, with minimal punctuation.      </span>     </dd>       </dl>  </div>  <div class="section" id="intllistformatter.changelog">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>8.5.0</td>       <td>        The class was added.       </td>      </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link IntlListFormatter::__construct} — Creates a new IntlListFormatter instance</li><li>{@link IntlListFormatter::format} — Format a list of items</li></ul></div>
 * 
 * @since 8.5
