    public const int WIDTH_NARROW = 2;

/**
 * <div id="intllistformatter.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">IntlListFormatter::__construct</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">IntlListFormatter::__construct</span> — <span class="dc-title">Creates a new IntlListFormatter instance</span></p> </div> <div class="refsect1 description" id="refsect1-intllistformatter.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>IntlListFormatter::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$locale</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$type</span><span class="initializer"> = <strong><span>{@link IntlListFormatter::TYPE_AND}</span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$width</span><span class="initializer"> = <strong><span>{@link IntlListFormatter::WIDTH_WIDE}</span></strong></span></span>)</div>  <p class="simpara">   Creates a new <span class="classname"><a href="https://php.net/manual/zh/class.intllistformatter.php" class="classname">IntlListFormatter</a></span> instance for the given locale.  </p> </div> <div class="refsect1 parameters" id="refsect1-intllistformatter.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">locale</span></dt>    <dd>     <span class="simpara">      The locale to use for formatting.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">type</span></dt>    <dd>     <span class="simpara">      The list type. One of the <strong><span>{@link IntlListFormatter::TYPE_*}</span></strong> constants:      <strong><span>{@link IntlListFormatter::TYPE_AND}</span></strong>,      <strong><span>{@link IntlListFormatter::TYPE_OR}</span></strong>, or      <strong><span>{@link IntlListFormatter::TYPE_UNITS}</span></strong>.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">width</span></dt>    <dd>     <span class="simpara">      The list width. One of the <strong><span>{@link IntlListFormatter::WIDTH_*}</span></strong> constants:      <strong><span>{@link IntlListFormatter::WIDTH_WIDE}</span></strong>,      <strong><span>{@link IntlListFormatter::WIDTH_SHORT}</span></strong>, or      <strong><span>{@link IntlListFormatter::WIDTH_NARROW}</span></strong>.     </span>    </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-intllistformatter.construct-errors">  <h3 class="title">错误／异常</h3>  <p class="simpara">   Throws an <span class="exceptionname"><a href="https://php.net/manual/zh/class.intlexception.php" class="exceptionname">IntlException</a></span> if the formatter cannot be created   (e.g. invalid locale or ICU version is below 67).  </p> </div> <div class="refsect1 changelog" id="refsect1-intllistformatter.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.5.0</td>      <td>       The class was added.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-intllistformatter.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link IntlListFormatter::format()} - Format a list of items</span></li>  </ul> </div></div>
