    public function __construct(string $locale, int $type = IntlListFormatter::TYPE_AND, int $width = IntlListFormatter::WIDTH_WIDE) {}

/**
 * <div id="intllistformatter.format" class="refentry"> <div class="refnamediv">  <h1 class="refname">IntlListFormatter::format</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">IntlListFormatter::format</span> — <span class="dc-title">Format a list of items</span></p> </div> <div class="refsect1 description" id="refsect1-intllistformatter.format-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>IntlListFormatter::format</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$list</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.singleton.php" class="type false" style="color:#EAB766">false</a></span></span></div>  <p class="simpara">   Formats a list of items as a locale-appropriate string.  </p> </div> <div class="refsect1 parameters" id="refsect1-intllistformatter.format-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">list</span></dt>    <dd>     <span class="simpara">      An array of strings to format as a list.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-intllistformatter.format-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The formatted list as a string, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> on failure.  </p> </div> <div class="refsect1 examples" id="refsect1-intllistformatter.format-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>IntlListFormatter::format()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$fmt </span><span style="color: #007700">= new </span><span style="color: #9876AA">IntlListFormatter</span><span style="color: #007700">(</span><span style="color: #DD0000">'en_US'</span><span style="color: #007700">, </span><span style="color: #9876AA">IntlListFormatter</span><span style="color: #007700">::</span><span style="color: #9876AA">TYPE_AND</span><span style="color: #007700">, </span><span style="color: #9876AA">IntlListFormatter</span><span style="color: #007700">::</span><span style="color: #9876AA">WIDTH_WIDE</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$fmt</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">format</span><span style="color: #007700">([</span><span style="color: #DD0000">'one'</span><span style="color: #007700">, </span><span style="color: #DD0000">'two'</span><span style="color: #007700">, </span><span style="color: #DD0000">'three'</span><span style="color: #007700">]);<br></span><span style="color: #FF8000">// one, two, and three<br><br></span><span style="color: #9876AA">\$fmt </span><span style="color: #007700">= new </span><span style="color: #9876AA">IntlListFormatter</span><span style="color: #007700">(</span><span style="color: #DD0000">'en_US'</span><span style="color: #007700">, </span><span style="color: #9876AA">IntlListFormatter</span><span style="color: #007700">::</span><span style="color: #9876AA">TYPE_OR</span><span style="color: #007700">, </span><span style="color: #9876AA">IntlListFormatter</span><span style="color: #007700">::</span><span style="color: #9876AA">WIDTH_WIDE</span><span style="color: #007700">);<br>echo </span><span style="color: #9876AA">\$fmt</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">format</span><span style="color: #007700">([</span><span style="color: #DD0000">'one'</span><span style="color: #007700">, </span><span style="color: #DD0000">'two'</span><span style="color: #007700">, </span><span style="color: #DD0000">'three'</span><span style="color: #007700">]);<br></span><span style="color: #FF8000">// one, two, or three<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-intllistformatter.format-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link IntlListFormatter::__construct()} - Creates a new IntlListFormatter instance</span></li>  </ul> </div></div>
